<?php
 if ( ! defined( 'ABSPATH' ) ) { exit; } require_once __DIR__ . '/class-mixer-all.php'; class HVM_Widget_SpeakersGrid extends HVM_Widget_Base { public function get_name() { return 'hvm_speakers_grid'; } public function get_title() { return 'Speakers Grid'; } public function get_icon() { return 'eicon-person'; } protected function register_controls() { $cm = '\Elementor\Controls_Manager'; $this->start_controls_section( 'spk_content', array( 'label' => 'Content', 'tab' => constant( "$cm::TAB_CONTENT" ) ) ); $this->add_control( 'source', array( 'label' => 'Source', 'type' => constant( "$cm::SELECT" ), 'default' => 'archive', 'options' => array( 'archive' => 'Current query (Speakers archive)', 'all' => 'All speakers', 'conference' => "This conference/summit's selected speakers", ), 'description' => 'Pick "This conference/summit\'s selected speakers" to show only the speakers chosen in this event\'s Speakers tab. Use "Current query" inside a Speakers Archive template.', ) ); $this->add_control( 'limit', array( 'label' => 'Max speakers', 'type' => constant( "$cm::NUMBER" ), 'min' => 1, 'default' => '', 'placeholder' => 'All', 'condition' => array( 'source!' => 'archive' ), ) ); $this->end_controls_section(); $this->start_controls_section( 'spk_layout', array( 'label' => 'Layout', 'tab' => constant( "$cm::TAB_CONTENT" ) ) ); $this->add_responsive_control( 'columns', array( 'label' => 'Columns', 'type' => constant( "$cm::NUMBER" ), 'min' => 1, 'max' => 6, 'default' => 4, 'tablet_default' => 2, 'mobile_default' => 1, 'selectors' => array( '{{WRAPPER}} .hvm-spk-grid' => '--hvm-spk-cols:{{VALUE}};' ), ) ); $this->add_responsive_control( 'gap', array( 'label' => 'Gap', 'type' => constant( "$cm::SLIDER" ), 'size_units' => array( 'px' ), 'range' => array( 'px' => array( 'min' => 0, 'max' => 60 ) ), 'default' => array( 'unit' => 'px', 'size' => 24 ), 'selectors' => array( '{{WRAPPER}} .hvm-spk-grid' => 'gap:{{SIZE}}{{UNIT}};' ), ) ); $this->end_controls_section(); $this->start_controls_section( 'spk_style', array( 'label' => 'Card', 'tab' => constant( "$cm::TAB_STYLE" ) ) ); $this->add_control( 'card_bg', array( 'label' => 'Card background', 'type' => constant( "$cm::COLOR" ), 'default' => '#F6F4F1', 'selectors' => array( '{{WRAPPER}} .hvm-spk-card' => 'background:{{VALUE}};' ) ) ); $this->add_control( 'card_border', array( 'label' => 'Border color', 'type' => constant( "$cm::COLOR" ), 'default' => '#E5E7EB', 'selectors' => array( '{{WRAPPER}} .hvm-spk-card' => 'border-color:{{VALUE}};' ) ) ); $this->add_control( 'name_color', array( 'label' => 'Name', 'type' => constant( "$cm::COLOR" ), 'default' => '#080A12', 'selectors' => array( '{{WRAPPER}} .hvm-spk-name' => 'color:{{VALUE}};' ) ) ); $this->add_control( 'role_color', array( 'label' => 'Role', 'type' => constant( "$cm::COLOR" ), 'default' => '#6B7280', 'selectors' => array( '{{WRAPPER}} .hvm-spk-role' => 'color:{{VALUE}};' ) ) ); $this->end_controls_section(); } private function query_ids() { $s = $this->get_settings_for_display(); $source = $s['source'] ?? 'archive'; $limit = ( isset( $s['limit'] ) && '' !== $s['limit'] ) ? max( 1, (int) $s['limit'] ) : -1; if ( 'conference' === $source ) { $ids = hvm_get( 'speakers' ); $ids = is_array( $ids ) ? array_map( 'absint', $ids ) : array(); if ( $limit > 0 ) { $ids = array_slice( $ids, 0, $limit ); } return $ids; } if ( 'archive' === $source && ( is_post_type_archive( 'speaker' ) || is_tax() ) && ! \Elementor\Plugin::$instance->editor->is_edit_mode() ) { global $wp_query; $ids = array(); if ( ! empty( $wp_query->posts ) ) { foreach ( $wp_query->posts as $p ) { $ids[] = (int) $p->ID; } } return $ids; } return get_posts( array( 'post_type' => 'speaker', 'numberposts' => $limit, 'orderby' => 'title', 'order' => 'ASC', 'post_status' => 'publish', 'fields' => 'ids', ) ); } protected function render() { $ids = $this->query_ids(); echo '<div class="hvm-spk-grid">'; if ( ! $ids ) { $this->empty_hint( 'Speakers Grid — no speakers found. Add Speakers, or (on a conference) pick some in the Speakers tab.' ); echo '</div>'; return; } foreach ( $ids as $id ) { $name = get_the_title( $id ); $link = get_permalink( $id ); $photo = get_the_post_thumbnail_url( $id, 'full' ); $role = hvm_get( 'role', $id ); $logo = function_exists( 'hvm_img_url' ) && hvm_get( 'company_logo', $id ) ? hvm_img_url( hvm_get( 'company_logo', $id ), 'full' ) : ''; echo '<a class="hvm-spk-card" href="' . esc_url( $link ) . '">'; echo '<span class="hvm-spk-photo">'; if ( $photo ) { echo '<img src="' . esc_url( $photo ) . '" alt="' . esc_attr( $name ) . '" loading="lazy" />'; } echo '</span>'; echo '<span class="hvm-spk-name">' . esc_html( $name ) . '</span>'; if ( '' !== (string) $role ) { echo '<span class="hvm-spk-role">' . esc_html( $role ) . '</span>'; } if ( '' !== $logo ) { echo '<span class="hvm-spk-logo"><img src="' . esc_url( $logo ) . '" alt="" loading="lazy" /></span>'; } echo '</a>'; } echo '</div>'; } } add_filter( 'hvm_mixer_widget_classes', function ( $classes ) { $classes[] = 'HVM_Widget_SpeakersGrid'; return $classes; } ); 